content:
case F_CR:
                                                /*previous=crlf and now !=' '*/
                                                goto endofheader;
                                        default:
                                                LM_DBG("spitting out [%c] in status %d\n", *tmp,
                                                                status);
                                                goto error;
                                }
                } /*char switch*/
        }        /*for*/

        /* Reached end of buffer */
        switch(status) {
                case URI_OR_TOKEN:
                case MAYBE_URI_END:
                case END:
                        saved_status = status;
                        foo = tmp;
        }

endofheader:
        if(to_b->display.len == 0)
                to_b->display.s = 0;
        status = saved_status;
        LM_DBG("end of header reached, state=%d\n", status);
        /* check if error*/
        switch(status) {
                case URI_OR_TOKEN:
                case MAYBE_URI_END:
                        to_b->uri.len = foo - to_b->uri.s;
                case END:
                        to_b->body.len = tmp - to_b->body.s;
                case E_PARA_VALUE:
                        break;
                default:
                        LM_ERR("invalid To -  unexpected "
                                        "end of header in state %d\n",
                                        status);
                        goto error;
        }
        return tmp;

error:
        free_to_params(to_b);
        to_b->error = PARSE_ERROR;
        return tmp;
}


void free_to_params(struct to_body *const tb)
{
        struct to_param *tp = tb->param_lst;
        struct to_param *foo;
        while(tp) {
                foo = tp->next;
                pkg_free(tp);
                tp = foo;
        }
        tb->param_lst = NULL;
}


void free_to(struct to_body *const tb)
{
        free_to_params(tb);
        pkg_free(tb);
}
